import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { AdminAuditEntry, AgentSpec } from '@cw/shared';

/** Per-agent secrets generated by the control plane (Key Vault on Azure). */
export interface AgentSecrets {
  oidcClientSecret: string;
  sessionSecret: string;
  /** Bearer token of the agent towards the control plane and the MCP gateway. */
  internalToken: string;
  /** LiteLLM virtual key of the agent (its only credential for the AI model, ADR-0029). */
  aiKey?: string;
}

interface RegistryData {
  agents: Array<{ spec: AgentSpec; secrets: AgentSecrets }>;
}

/** Desired state of all agents (the runtime holds the actual state). */
export class AgentRegistry {
  private data: RegistryData = { agents: [] };
  private readonly file: string;
  private writing = Promise.resolve();

  constructor(dataDir: string) {
    this.file = path.join(dataDir, 'admin', 'agents.json');
  }

  async load() {
    await mkdir(path.dirname(this.file), { recursive: true });
    try {
      this.data = JSON.parse(await readFile(this.file, 'utf8')) as RegistryData;
      // migrate entries created before a secret existed
      let migrated = false;
      for (const a of this.data.agents) {
        if (!a.secrets.internalToken) {
          a.secrets.internalToken = randomBytes(32).toString('base64url');
          migrated = true;
        }
      }
      if (migrated) await this.persist();
    } catch {
      await this.persist();
    }
  }

  private persist() {
    this.writing = this.writing.then(async () => {
      const tmp = `${this.file}.tmp`;
      await writeFile(tmp, JSON.stringify(this.data, null, 2), { mode: 0o600 });
      await rename(tmp, this.file);
    });
    return this.writing;
  }

  list(): AgentSpec[] {
    return this.data.agents.map((a) => a.spec).sort((a, b) => a.agentId.localeCompare(b.agentId));
  }

  findByToken(token: string) {
    return this.data.agents.find((a) => a.secrets.internalToken === token);
  }

  get(agentId: string) {
    return this.data.agents.find((a) => a.spec.agentId === agentId);
  }

  async put(spec: AgentSpec, secrets?: AgentSecrets) {
    const existing = this.get(spec.agentId);
    const entry = { spec, secrets: secrets ?? existing?.secrets ?? newSecrets() };
    this.data.agents = [...this.data.agents.filter((a) => a.spec.agentId !== spec.agentId), entry];
    await this.persist();
    return entry;
  }

  async delete(agentId: string) {
    this.data.agents = this.data.agents.filter((a) => a.spec.agentId !== agentId);
    await this.persist();
  }
}

export const newSecrets = (): AgentSecrets => ({
  oidcClientSecret: randomBytes(24).toString('base64url'),
  sessionSecret: randomBytes(32).toString('base64url'),
  internalToken: randomBytes(32).toString('base64url'),
});

/** Admin actions log (JSON lines). */
export class AdminAudit {
  private readonly file: string;

  constructor(dataDir: string) {
    this.file = path.join(dataDir, 'admin', 'audit.jsonl');
  }

  async write(e: Omit<AdminAuditEntry, 'at'>) {
    await mkdir(path.dirname(this.file), { recursive: true });
    await writeFile(this.file, `${JSON.stringify({ at: new Date().toISOString(), ...e })}\n`, { flag: 'a' });
  }

  async list(limit = 200, filter?: (e: AdminAuditEntry) => boolean): Promise<AdminAuditEntry[]> {
    const text = await readFile(this.file, 'utf8').catch(() => '');
    const all = text.split('\n').filter(Boolean).map((l) => JSON.parse(l) as AdminAuditEntry).reverse();
    return (filter ? all.filter(filter) : all).slice(0, limit);
  }
}
